import {N,DT,STEPS,rng,groups,colors,edges,createTrial,classify} from './model.js';
const $=s=>document.querySelector(s);const presets=[['Peaches','Long walks across your unattended drink.',45,.9,75],['Clementine','Here for a good time. And the citrus.',78,.45,85],['Fig','A little mysterious. Mostly stationary.',12,.05,35],['Cherry','Catch me if you can.',95,.9,90],['Olive','Let’s take this one step at a time.',35,.45,65],['Mango','Your fruit bowl. Friday. Be there.',55,.9,95]];
let profile=0,guess=null,running=false,trial=null,last=null,frame=null,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,shareSettings=null;const flashes=new Float32Array(N);const random=rng(321);const nodes=Array.from({length:N},(_,i)=>{const g=i>>5,angle=random()*Math.PI*2,r=Math.sqrt(random());const centers=[[.23,.37],[.23,.7],[.45,.32],[.6,.53],[.45,.77],[.8,.5]];return {x:centers[g][0]+Math.cos(angle)*r*.095,y:centers[g][1]+Math.sin(angle)*r*.13,g}});
$('#edgeCount').textContent=edges.length;$('#flyPhoto').src='fly.jpg';$('#flyPhoto').hidden=false;$('#specimenFallback').hidden=true;$('#photoCredit').innerHTML='Photo: <a href="https://commons.wikimedia.org/wiki/File:Drosophila_melanogaster_%E2%99%80_(38978426500).jpg" target="_blank" rel="noreferrer">Rolf Dietrich Brecher / Wikimedia Commons</a>, <a href="https://creativecommons.org/licenses/by/2.0/" target="_blank" rel="noreferrer">CC BY 2.0</a>. Cropped for display. All candidates use the same illustrative photograph.';
const brain=$('#brain'),raster=$('#raster');function setup(canvas){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d)}const c=canvas.getContext('2d');c.setTransform(d,0,0,d,0,0);return [c,r.width,r.height]}
function drawRaster(){const [c,w,h]=setup(raster);c.clearRect(0,0,w,h);c.strokeStyle='#293125';for(let i=1;i<6;i++){c.beginPath();c.moveTo(i*w/6,0);c.lineTo(i*w/6,h);c.stroke()}if(!trial)return;for(const [t,n] of trial.spikes){c.fillStyle=colors[n>>5];c.globalAlpha=.65;c.fillRect(t/STEPS*w,n/N*h,1.3,1.2)}c.globalAlpha=1}
function draw(t){const [c,w,h]=setup(brain);c.clearRect(0,0,w,h);const pos=n=>[n.x*w,n.y*h];c.lineWidth=.55;for(const e of edges){const a=pos(nodes[e.from]),b=pos(nodes[e.to]);c.strokeStyle=flashes[e.from]>.5?colors[nodes[e.from].g]:'#608055';c.globalAlpha=flashes[e.from]>.5?.23:.065;c.beginPath();c.moveTo(...a);c.lineTo(...b);c.stroke()}c.globalAlpha=1;nodes.forEach((n,i)=>{const [x,y]=pos(n),f=paused?0:flashes[i];c.fillStyle=colors[n.g];c.globalAlpha=.3+.7*f;if(f>.3){c.shadowColor=colors[n.g];c.shadowBlur=f*13}c.beginPath();c.arc(x,y,1.5+f*2.3,0,Math.PI*2);c.fill();c.shadowBlur=0;flashes[i]*=.88});c.globalAlpha=.6;c.font='11px "Space Grotesk",sans-serif';c.textAlign='center';[[.23,.19,'VISUAL'],[.21,.86,'CHEMICAL'],[.45,.14,'INTEGRATION'],[.62,.32,'DRIVE'],[.49,.87,'INHIBITION'],[.82,.7,'OUTPUT']].forEach(([x,y,s])=>{c.fillStyle='#a8b79f';c.fillText(s,x*w,y*h)});c.globalAlpha=1;if(!paused||running)frame=requestAnimationFrame(draw);else frame=null}
function ensureDraw(){if(frame===null)frame=requestAnimationFrame(draw)}
function settings(){return {movement:+$('#movement').value/100,chemical:+$('#chemical').value,contrast:+$('#contrast').value/100}}
function sync(){ $('#movementOut').textContent=$('#movement').value+'%';$('#contrastOut').textContent=$('#contrast').value+'%'}
function reset(){last=null;trial=null;guess=null;shareSettings=null;flashes.fill(0);$('#activeCount').innerHTML='0<small> / 192</small>';$('#pursuitValue').innerHTML='0<small> Hz</small>';$('#timeValue').innerHTML='0.00<small> s</small>';$('#resultEyebrow').textContent='YOUR PREDICTION';$('#resultTitle').textContent='Will there be chemistry?';$('#resultDetail').textContent='Make your call. Otto gets the final say.';$('#prediction').hidden=false;document.querySelectorAll('[data-guess]').forEach(b=>b.classList.remove('selected'));$('#runButton').textContent='Pick your prediction';$('#runButton').disabled=true;$('#shareButton').hidden=true;$('#shareButton').textContent='Copy this encounter ↗';$('#statusLabel').textContent='READY';drawRaster();ensureDraw()}
function choose(g){if(running)return;if(!['pass','pursue'].includes(g))throw Error('Prediction must be pass or pursue');guess=g;document.querySelectorAll('[data-guess]').forEach(b=>b.classList.toggle('selected',b.dataset.guess===g));$('#runButton').disabled=false;$('#runButton').textContent='Introduce them →'}
function lock(v){document.querySelectorAll('input,select,#nextProfile,[data-guess]').forEach(e=>e.disabled=v)}
async function run(){if(running||!guess)return;if(last){reset();return}running=true;lock(true);shareSettings={...settings(),profile,guess};trial=createTrial(settings());$('#runButton').disabled=true;$('#runButton').textContent='Encounter in progress…';$('#statusLabel').textContent='SIMULATING';$('#statusDot').classList.add('running');$('#resultEyebrow').textContent='ENCOUNTER IN PROGRESS';$('#resultTitle').textContent='Let’s see what happens.';$('#resultDetail').textContent='Watch sensory input travel through the circuit.';ensureDraw();await new Promise(resolve=>{function step(){let s;for(let k=0;k<4;k++){s=trial.tick();s.fired.forEach(i=>flashes[i]=1);if(s.done)break}$('#activeCount').innerHTML=s.fired.length+'<small> / 192</small>';$('#pursuitValue').innerHTML=s.outputHz.toFixed(1)+'<small> Hz</small>';$('#timeValue').innerHTML=(s.step*DT).toFixed(2)+'<small> s</small>';drawRaster();if(!s.done)setTimeout(step,25);else{last={outcome:classify(s.outputHz),outputHz:s.outputHz};resolve()}}step()});running=false;lock(false);$('#statusDot').classList.remove('running');$('#statusLabel').textContent='COMPLETE';$('#resultEyebrow').textContent=last.outcome==='unclear'?'NO CLEAR RESPONSE':guess===last.outcome?'YOU CALLED IT':'OTTO SURPRISED YOU';$('#resultTitle').textContent=last.outcome==='pursue'?'Otto made his move. ♡':last.outcome==='pass'?'Not much of a spark.':'The circuit is undecided.';$('#resultDetail').textContent=`${last.outputHz.toFixed(1)} output spikes/neuron/s in the final 3 seconds. ${last.outcome==='pursue'?'Above the model’s pursuit threshold.':last.outcome==='pass'?'Below the model’s response threshold.':'Between the model’s decision thresholds.'}`;$('#prediction').hidden=true;$('#runButton').disabled=false;$('#runButton').textContent='Try another encounter ↗';$('#shareButton').hidden=false;return last}
function applyPreset(index){profile=index;const p=presets[index];$('#profileName').textContent=p[0];$('#profileBio').textContent=p[1];$('#movement').value=p[2];$('#chemical').value=p[3];$('#contrast').value=p[4];$('#candidateNumber').textContent=String(index+1).padStart(2,'0')+'—06';sync();reset()}
document.querySelectorAll('[data-guess]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.guess)));$('#runButton').addEventListener('click',run);$('#nextProfile').addEventListener('click',()=>applyPreset((profile+1)%presets.length));document.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',()=>{sync();reset()}));['#scienceOpen','#modelOpen'].forEach(s=>$(s).addEventListener('click',()=>$('#science').showModal()));$('#scienceClose').addEventListener('click',()=>$('#science').close());$('#science').addEventListener('click',e=>{if(e.target===$('#science')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#motionToggle').addEventListener('click',()=>{paused=!paused;$('#motionToggle').textContent=paused?'Show spike flashes':'Reduce spike flashes';ensureDraw()});if(paused)$('#motionToggle').textContent='Show spike flashes';
$('#shareButton').addEventListener('click',async()=>{if(!shareSettings)return;const u=new URL(location.href);u.hash=new URLSearchParams({p:shareSettings.profile,m:Math.round(shareSettings.movement*100),c:shareSettings.chemical,v:Math.round(shareSettings.contrast*100)}).toString();try{await navigator.clipboard.writeText(u.href);$('#shareButton').textContent='Encounter link copied ✓'}catch{$('#shareButton').textContent='Copy the link from the address bar';history.replaceState(null,'',u)}});
const params=new URLSearchParams(location.hash.slice(1));if(params.has('p')){const p=Number(params.get('p'));if(Number.isInteger(p)&&p>=0&&p<6)applyPreset(p);for(const [key,id,min,max]of [['m','movement',0,100],['v','contrast',0,100]]){if(params.has(key)){const v=Number(params.get(key));if(Number.isFinite(v)&&v>=min&&v<=max)$('#'+id).value=v}}if(['0.9','0.45','0.05'].includes(params.get('c')))$('#chemical').value=params.get('c');sync()}
window.addEventListener('resize',()=>{drawRaster();ensureDraw()});drawRaster();ensureDraw();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'run_courtship_encounter',description:'Run a synthetic courtship simulation with the visible candidate settings and a prediction; return the actual model outcome.',inputSchema:{type:'object',properties:{prediction:{type:'string',enum:['pass','pursue']}},required:['prediction'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||!['pass','pursue'].includes(input.prediction))throw Error('Invalid prediction');if(running)throw Error('An encounter is already running');if(last)reset();choose(input.prediction);return await run()}})).catch(()=>{})}catch{}}
